/* eslint-disable @typescript-eslint/no-require-imports -- standalone Node script */
/*
 * Evidence capture for the gamification product review (docs/GAMIFICATION_PRODUCT_REVIEW.md). Drives the REAL web export in MOCK mode (synthetic data, simulated Apple
 * Health provider; not native). Two parts:
 *   Part 1: a brand-new account, using only UI interactions (taps and typing).
 *   Part 2: the same app opened on persisted mock-store data with a 75-day history (generated by the dev store, then placed in localStorage). The screens are the real
 *           screens; only the history behind them is seeded. Each shot says which part it came from in its file name (ui- or seed-).
 * Usage: pnpm export:web && node e2e/review-capture.cjs [seedFile]   Output: docs/review-shots/*.png and docs/review-shots/results.json
 */
const { chromium } = require('playwright');
const fs = require('node:fs');
const crypto = require('node:crypto');
const { createAccountViaPin, onboard } = require('./auth.cjs');

const OUT = process.env.REVIEW_OUT || '../../docs/review-shots';
const SEED = process.argv[2] || '/tmp/seeds/veteran.json';
fs.mkdirSync(OUT, { recursive: true });
const results = {};
const base = 'http://127.0.0.1:8099';
const hash = (b) => crypto.createHash('sha1').update(b).digest('hex').slice(0, 10);

async function main() {
  const { serve } = await import('./serve.mjs');
  const srv = await serve(8099);
  const browser = await chromium.launch();
  const ctx = await browser.newContext({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 1.5,
  });
  const p = await ctx.newPage();
  p.setDefaultTimeout(6000);
  const errors = [];
  p.on('pageerror', (e) => errors.push(e.message));
  const go = async (path, wait = 1000) => {
    await p.evaluate((u) => {
      window.history.pushState({}, '', u);
      window.dispatchEvent(new PopStateEvent('popstate'));
    }, path);
    await p.waitForTimeout(wait);
  };
  const body = () => p.evaluate(() => document.body.innerText);
  const btn = (n) => p.getByRole('button', { name: n }).last();
  const shot = async (name, opts = {}) => {
    const file = `${OUT}/${name}.png`;
    await p.screenshot({ path: file, ...opts });
    return file;
  };
  const scrollTo = async (text) => {
    await p
      .getByText(text, { exact: false })
      .last()
      .scrollIntoViewIfNeeded()
      .catch(() => {});
    await p.waitForTimeout(400);
  };
  const xp = async () => {
    const m = /(\d+) XP\b/.exec(await body());
    return m ? Number(m[1]) : null;
  };
  const pulseHash = async () => {
    const el = p.getByLabel(/Pulse, your guide/).first();
    const buf = await el.screenshot().catch(() => null);
    return buf ? { hash: hash(buf), buf } : null;
  };
  const step = async (key, fn) => {
    try {
      results[key] = { ok: true, ...(await fn()) };
    } catch (e) {
      await p.screenshot({ path: `${OUT}/fail-${key}.png` }).catch(() => {});
      console.log((await body().catch(() => '')).split('\n').slice(0, 14).join(' | '));
      results[key] = { ok: false, error: String(e.message).split('\n')[0] };
    }
    console.log(results[key].ok ? 'OK  ' : 'FAIL', key, results[key].ok ? '' : results[key].error);
  };

  // ---------------- Part 1: a new account, UI only ----------------
  const part1 = process.env.PART2_ONLY !== '1';
  if (part1) {
    await p.goto(base);
    await p.waitForTimeout(2500);
    await createAccountViaPin(p);
    await onboard(p);
    await p.waitForTimeout(2200);
    await step('ui-home-new', async () => {
      await shot('ui-01-home-new-user-top');
      await scrollTo('Your progress');
      await shot('ui-02-home-new-user-progress-card');
      const pu = await pulseHash();
      if (pu) fs.writeFileSync(`${OUT}/ui-03-pulse-new-user.png`, pu.buf);
      return {
        xp: await xp(),
        pulseHash: pu?.hash ?? null,
        text: (await body())
          .split('\n')
          .filter((l) => /Level|XP|streak|quest|Move|Log a meal|habit|session/i.test(l))
          .slice(0, 12),
      };
    });
    // Journey B (part): habit + quest on Home
    await step('journeyB-habit-quest', async () => {
      await go('/');
      await p.getByLabel('New habit').last().fill('Stretch two minutes');
      await btn('Add habit').click();
      await p.waitForTimeout(800);
      await scrollTo('Today’s quests');
      const before = await body();
      await shot('ui-04-home-quests-before');
      const hadHabitQuest = /Tick off one habit/.test(before);
      await p
        .getByRole('checkbox', { name: /Stretch two minutes: not done today/ })
        .last()
        .click();
      await p.waitForTimeout(1200);
      await scrollTo('Today’s quests');
      await shot('ui-05-home-quests-after-habit-tick');
      const after = await body();
      const xp1 = await xp();
      const streakOf = async () =>
        (await body()).match(
          /Move for 10 minutes or tick a habit to start a streak\.|\d+-day streak/,
        )?.[0];
      const streak1 = await streakOf();
      // Does the card ever catch up on its own? Wait just over a minute with no other action.
      await p.waitForTimeout(62000);
      await scrollTo('Today’s quests');
      await shot('ui-05b-home-62s-after-habit-tick-no-other-action');
      const staleCheck = {
        xpAt1s: xp1,
        xpAt63s: await xp(),
        streakAt1s: streak1,
        streakAt63s: await streakOf(),
      };
      return {
        staleCheck,
        hadHabitQuestToday: hadHabitQuest,
        questsListed:
          before.match(
            /(Move for 10 minutes|Tick off one habit|Log a meal|Try a gentle or low-impact session)/g,
          ) ?? [],
        questLinesAfter: after
          .split('\n')
          .filter((l) => /Done|of 1|of 10/.test(l))
          .slice(0, 8),
        xpAfter: await xp(),
      };
    });
    // Journey A: first workout by UI
    await step('journeyA-first-workout', async () => {
      const xp0 = await xp();
      await p.getByRole('tab', { name: 'Dance', exact: true }).click();
      await p.waitForTimeout(1200);
      await scrollTo('Quick Fit');
      await shot('ui-06-workouts-tab-new-user');
      await btn(/Quick Fit/).click();
      await btn('Start guided session').click();
      await p.getByRole('button', { name: 'Start', exact: true }).last().click();
      await p.getByText('Get ready', { exact: false }).last().waitFor({ state: 'visible' });
      await p.waitForTimeout(3600);
      await shot('ui-06b-workout-in-progress');
      await p.waitForTimeout(3500);
      await btn('End session').click();
      await p.getByText('End this session?', { exact: false }).last().waitFor({ state: 'visible' });
      await btn('Keep going').click();
      await btn('End session').click();
      await btn('End session').click();
      await p.getByText('You moved for', { exact: false }).last().waitFor({ state: 'visible' });
      await p.waitForTimeout(900);
      await shot('ui-07-workout-completion-screen');
      const completionText = (await body())
        .split('\n')
        .filter((l) => l.trim())
        .slice(0, 25);
      await btn('Save what I did').click();
      await p.waitForTimeout(1500);
      await shot('ui-08-after-save');
      await btn('Continue')
        .click()
        .catch(() => {});
      await go('/');
      await scrollTo('Your progress');
      await shot('ui-09-home-after-first-workout');
      return {
        xpBefore: xp0,
        xpAfter: await xp(),
        completionScreenMentionsXp: /\bXP\b/.test(completionText.join(' ')),
        completionText: completionText.slice(0, 14),
      };
    });
    // Journey C: Apple Health simulated import via the Settings switch
    await step('journeyC-apple-health', async () => {
      const xp0 = await xp();
      await go('/privacy');
      await scrollTo('Apple Health');
      await shot('ui-10-settings-progress-and-health-off');
      await p.getByRole('switch', { name: 'Import workouts from Apple Health' }).last().click();
      await p.waitForTimeout(1500);
      await scrollTo('Apple Health');
      await shot('ui-11-settings-health-imported');
      const msg1 = (await body()).match(/Imported \d+ workouts|No new workouts to import/)?.[0];
      await go('/');
      const xp1 = await xp();
      await go('/privacy');
      await btn('Import now').click();
      await p.waitForTimeout(1200);
      const msg2 = (await body()).match(/Imported \d+ workouts|No new workouts to import/)?.[0];
      await go('/');
      await scrollTo('Your progress');
      await shot('ui-12-home-after-health-import');
      return {
        xpBefore: xp0,
        xpAfterImport: xp1,
        xpAfterSecondImport: await xp(),
        firstMessage: msg1,
        secondMessage: msg2,
      };
    });
    // Journey D: league by UI
    await step('journeyD-league', async () => {
      await go('/friends');
      await p.getByLabel('Public name').last().fill('my_name');
      await btn('Use this name').click();
      await p.waitForTimeout(800);
      await p.getByLabel('Their public name').last().fill('sample_ama');
      await btn('Send request').click();
      await p.waitForTimeout(900);
      await scrollTo('Friends league');
      await shot('ui-13-friends-league-before-join');
      await p.getByRole('switch', { name: 'Join the friends league' }).last().click();
      await p.waitForTimeout(1200);
      await scrollTo('Friends league');
      await shot('ui-14-friends-league-joined');
      const joined = await body();
      const rows = joined.split('\n').filter((l) => /XP/.test(l) && /^\d\./.test(l.trim()));
      await p.getByRole('switch', { name: 'Join the friends league' }).last().click();
      await p.waitForTimeout(1000);
      const left = await body();
      return {
        rows,
        leftShowsRows: /\d\. .* XP/.test(left.split('Friends league')[1] ?? ''),
        leagueText: joined
          .split('\n')
          .filter((l) => /league|capped|joined|XP this week/i.test(l))
          .slice(0, 6),
      };
    });
    // Journey E (UI part): a group goal created by UI, its card
    await step('journeyE-group-ui', async () => {
      await go('/friends');
      await p
        .getByText('Couple goal', { exact: false })
        .last()
        .click()
        .catch(() => {});
      await p.getByLabel('Name it').last().fill('Move together');
      await p
        .getByRole('switch', { name: /Invite sample_ama/ })
        .last()
        .click()
        .catch(() => {});
      await btn('Create').click();
      await p.waitForTimeout(1200);
      await p.mouse.move(195, 420);
      await p.mouse.wheel(0, 1200);
      await p.waitForTimeout(600);
      await shot('ui-15-friends-group-goal-card');
      return {
        text: (await body())
          .split('\n')
          .filter((l) =>
            /Move together|Group goals are cooperative|shared|target|total|goal/i.test(l),
          )
          .slice(0, 8),
      };
    });
    await step('ui-other-screens', async () => {
      await go('/dance');
      await scrollTo('This week');
      await shot('ui-16-workouts-weekly-card');
      await go('/food');
      await shot('ui-17-nutrition-tab');
      await go('/progress');
      await scrollTo('Badges');
      await shot('ui-18-progress-badges-new-user');
      await go('/privacy');
      await scrollTo('Progress and rewards');
      await shot('ui-19-settings-progress-and-rewards');
      return {
        settingsText: (await body())
          .split('\n')
          .filter((l) => /notification|animation|motion|reminder/i.test(l))
          .slice(0, 8),
      };
    });
    results.part1PageErrors = errors.splice(0);
  }

  // ---------------- Part 2: persisted 75-day history, real screens ----------------
  const seed = JSON.parse(fs.readFileSync(SEED, 'utf8'));
  const ctx2 = await browser.newContext({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 1.5,
  });
  await ctx2.addInitScript((s) => {
    for (const [k, v] of Object.entries(s))
      if (!localStorage.getItem(k)) localStorage.setItem(k, v);
  }, seed);
  const q = await ctx2.newPage();
  q.setDefaultTimeout(6000);
  const errors2 = [];
  q.on('pageerror', (e) => errors2.push(e.message));
  const qgo = async (path, wait = 1000) => {
    await q.evaluate((u) => {
      window.history.pushState({}, '', u);
      window.dispatchEvent(new PopStateEvent('popstate'));
    }, path);
    await q.waitForTimeout(wait);
  };
  const qbody = () => q.evaluate(() => document.body.innerText);
  const qscroll = async (text) => {
    await q
      .getByText(text, { exact: false })
      .last()
      .scrollIntoViewIfNeeded()
      .catch(() => {});
    await q.waitForTimeout(400);
  };
  await q.goto(base);
  await q.waitForTimeout(1500);
  const { enterPin } = require('./auth.cjs');
  const qbtn = (n) =>
    q.getByRole('button', { name: n, exact: true }).locator('visible=true').last();
  if (
    await q
      .getByText('Protect your account with a PIN')
      .first()
      .isVisible()
      .catch(() => false)
  ) {
    // The account layer asks for a PIN on a phone that has none; set one the way a person would.
    await enterPin(q);
    await q.getByText('Confirm your PIN').first().waitFor({ state: 'visible' });
    await enterPin(q);
    await qbtn('Protect my account').click();
    await q.waitForTimeout(500);
  }
  await step('seed-home-levelup-moment', async () => {
    // Opening Home on data that is above the stored "last congratulated" level triggers the level-up moment.
    const t0 = await qbody();
    const signedIn = !/Welcome to Locked In Fitness/.test(t0) || /Level \d+/.test(t0);
    await q.waitForTimeout(600);
    await q.screenshot({ path: `${OUT}/seed-01-home-levelup-moment.png` });
    await q.waitForTimeout(3500);
    await q.screenshot({ path: `${OUT}/seed-02-home-after-moment.png` });
    const b = await qbody();
    return {
      signedInOnSeed: signedIn,
      level: /Level (\d+)/.exec(b)?.[1] ?? null,
      xp: /(\d+) XP\b/.exec(b)?.[1] ?? null,
      momentText: /Level \d+! You earned it\./.test(t0),
    };
  });
  await step('seed-pulse-accessories', async () => {
    const el = q.getByLabel(/Pulse, your guide/).first();
    const buf = await el.screenshot();
    fs.writeFileSync(`${OUT}/seed-03-pulse-with-accessories.png`, buf);
    const fresh = fs.existsSync(`${OUT}/ui-03-pulse-new-user.png`)
      ? fs.readFileSync(`${OUT}/ui-03-pulse-new-user.png`)
      : null;
    return {
      veteranPulseHash: hash(buf),
      newUserPulseHash: fresh ? hash(fresh) : null,
      differs: fresh ? hash(buf) !== hash(fresh) : null,
    };
  });
  await step('seed-home-progress-card', async () => {
    await qscroll('Your progress');
    await q.screenshot({ path: `${OUT}/seed-04-home-progress-card-veteran.png` });
    const b = await qbody();
    return {
      lines: b
        .split('\n')
        .filter((l) => /Level|XP|streak|Planned rest|week|quest/i.test(l))
        .slice(0, 10),
    };
  });
  await step('seed-progress-badges-season', async () => {
    await qgo('/progress');
    await qscroll('Badges');
    await q.screenshot({ path: `${OUT}/seed-05-progress-badges.png` });
    await qscroll('Season challenge');
    await q.screenshot({ path: `${OUT}/seed-06-progress-season-and-wardrobe.png` });
    const b = await qbody();
    return {
      badgeLines: b
        .split('\n')
        .filter((l) => /in a row|Level \d+|Ten quests|Rested well|Season finisher/.test(l)),
      seasonLines: b
        .split('\n')
        .filter((l) =>
          /season|wardrobe|Headband|Wristbands|Cape|scarf|Spring|Summer|Winter/i.test(l),
        )
        .slice(0, 8),
    };
  });
  await step('seed-friends-league-group', async () => {
    await qgo('/friends');
    await qscroll('Friends league');
    await q.screenshot({ path: `${OUT}/seed-07-friends-league.png` });
    await q.mouse.move(195, 420);
    await q.mouse.wheel(0, 760);
    await q.waitForTimeout(600);
    await q.screenshot({ path: `${OUT}/seed-08-group-goal-at-target.png` });
    const b = await qbody();
    return {
      leagueRows: b.split('\n').filter((l) => /^\d\..*XP/.test(l.trim())),
      groupLines: b
        .split('\n')
        .filter((l) =>
          /Move together|target|total|Couple|shared|Group goals are cooperative/i.test(l),
        )
        .slice(0, 8),
      celebrationOrRewardText: /goal reached|congrat|you did it|complete!/i.test(b),
    };
  });
  await step('seed-workouts-tab', async () => {
    await qgo('/dance');
    await qscroll('This week');
    await q.screenshot({ path: `${OUT}/seed-09-workouts-weekly-card-veteran.png` });
    return {};
  });
  results.part2PageErrors = errors2;
  const prior =
    fs.existsSync(`${OUT}/results.json`) && !part1
      ? JSON.parse(fs.readFileSync(`${OUT}/results.json`, 'utf8'))
      : {};
  fs.writeFileSync(`${OUT}/results.json`, JSON.stringify({ ...prior, ...results }, null, 2));
  await browser.close();
  srv.close();
}
main().catch((e) => {
  console.error(e);
  process.exit(1);
});
